package com.jsh.erp.service;

import com.alibaba.fastjson.*;
import com.jsh.erp.datasource.entities.User;
import com.jsh.erp.datasource.entities.UserBusiness;
import com.jsh.erp.exception.BusinessRunTimeException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import javax.annotation.Resource;
import java.math.BigDecimal;
import java.util.*;
import java.util.regex.*;

@Service
public class FactoryProgressService {
 @Resource private JdbcTemplate jdbc;
 @Resource private UserService users;
 @Resource private UserBusinessService business;
 private void require(boolean b,String s){if(!b)throw new BusinessRunTimeException(409,s);}
 private long num(Object v){return ((Number)v).longValue();}
 private BigDecimal dec(Object v){return v==null?BigDecimal.ZERO:new BigDecimal(v.toString());}
 private List<Long> ids(String value){List<Long> r=new ArrayList<>();Matcher m=Pattern.compile("\\d+").matcher(value==null?"":value);while(m.find())r.add(Long.valueOf(m.group()));return r;}
 private static class Viewer {User user;boolean all,money;List<Integer> workshops=new ArrayList<>();Set<String> menus=new HashSet<>();}
 private Viewer viewer()throws Exception{
  Viewer v=new Viewer();v.user=users.getCurrentUser();User u=v.user;require(u!=null&&u.getTenantId()!=null&&u.getTenantId()>0,"请使用业务租户账号");long tenant=u.getTenantId();
  Set<Long> granted=new HashSet<>();for(UserBusiness role:business.getBasicData(u.getId().toString(),"UserRole"))for(Long roleId:ids(role.getValue()))for(UserBusiness f:business.getBasicData(roleId.toString(),"RoleFunctions"))granted.addAll(ids(f.getValue()));
  for(Map<String,Object> menu:jdbc.queryForList("SELECT id,url FROM jsh_function WHERE enabled=1 AND IFNULL(delete_flag,'0')='0'"))if(granted.contains(num(menu.get("id"))))v.menus.add(menu.get("url").toString());
  v.all=u.getId().equals(tenant);v.money=v.all||v.menus.contains("/bill/sale_order");
  for(Map<String,Object> c:jdbc.queryForList("SELECT reviewer_id,coordinator_id,workshop1_director_id,workshop2_director_id,workshop3_director_id FROM jsh_factory_production_config WHERE tenant_id=?",tenant)){
   if(Objects.equals(c.get("coordinator_id"),u.getId())||Objects.equals(c.get("reviewer_id"),u.getId()))v.all=true;
   for(int w=1;w<=3;w++)if(c.get("workshop"+w+"_director_id")!=null&&num(c.get("workshop"+w+"_director_id"))==u.getId())v.workshops.add(w);
  }
  if(jdbc.queryForObject("SELECT COUNT(*) FROM jsh_factory_sales_config WHERE tenant_id=? AND reviewer_id=?",Integer.class,tenant,u.getId())>0){v.all=true;v.money=true;}
  for(String table:Arrays.asList("jsh_factory_release_config","jsh_factory_return_config","jsh_factory_change_config")){
   String column=table.equals("jsh_factory_release_config")?"leader_ids_json":"leader_ids";for(String value:jdbc.queryForList("SELECT "+column+" FROM "+table+" WHERE tenant_id=?",String.class,tenant))if(JSON.parseArray(value,Long.class).contains(u.getId()))v.all=true;
  }
  if(jdbc.queryForObject("SELECT COUNT(*) FROM jsh_factory_shipping_config WHERE tenant_id=? AND finance_id=?",Integer.class,tenant,u.getId())>0)v.money=true;
  require(v.menus.contains("/factory/order_progress")||v.all||!v.workshops.isEmpty(),"没有订单进度看板权限");return v;
 }
 public Map<String,Object> options()throws Exception{Viewer v=viewer();Map<String,Object> r=new HashMap<>();r.put("allOrders",v.all);r.put("workshops",v.workshops);r.put("scope",v.all?"全部订单":v.workshops.isEmpty()?"本人订单":"本人订单及分配到本车间的任务");return r;}
 private String scope(Viewer v,List<Object> args){if(v.all)return "";args.add(v.user.getId());String q=" AND (f.created_by=?";if(!v.workshops.isEmpty()){q+=" OR EXISTS(SELECT 1 FROM jsh_factory_workshop_task w WHERE w.tenant_id=f.tenant_id AND w.head_id=f.head_id AND w.workshop_no IN("+String.join(",",Collections.nCopies(v.workshops.size(),"?"))+"))";args.addAll(v.workshops);}return q+")";}
 @Transactional(readOnly=true)
 public Map<String,Object> list(String keyword,int page)throws Exception{
  Viewer v=viewer();require(keyword.length()<=100&&page>0&&page<=100000,"查询参数无效");List<Object> args=new ArrayList<>(Arrays.asList(v.user.getTenantId(),"%"+keyword+"%","%"+keyword+"%"));String from=" FROM jsh_factory_sales_order f JOIN jsh_depot_head h ON h.id=f.head_id AND h.tenant_id=f.tenant_id LEFT JOIN jsh_supplier c ON c.id=h.organ_id AND c.tenant_id=f.tenant_id LEFT JOIN jsh_factory_production_task t ON t.head_id=f.head_id AND t.tenant_id=f.tenant_id LEFT JOIN jsh_factory_shipment sh ON sh.head_id=f.head_id AND sh.tenant_id=f.tenant_id WHERE f.tenant_id=? AND IFNULL(h.delete_flag,'0')='0' AND (h.number LIKE ? OR c.supplier LIKE ?)"+scope(v,args);Map<String,Object> r=new HashMap<>();r.put("total",jdbc.queryForObject("SELECT COUNT(*)"+from,Long.class,args.toArray()));args.add((page-1)*10);r.put("rows",jdbc.queryForList("SELECT f.head_id,h.number,c.supplier customer_name,f.delivery_date,f.workflow_status,t.workflow_status production_state,sh.workflow_status shipping_state"+from+" ORDER BY f.head_id DESC LIMIT 10 OFFSET ?",args.toArray()));return r;
 }
 private String routeKey(int line,int stage,int workshop){return line+"|"+stage+"|"+workshop;}
 private void add(Map<String,Object> row,String key,Object qty){row.put(key,dec(row.get(key)).add(dec(qty)));}
 private Map<String,Object> jump(Viewer v,String title,String url,String key,Object value,boolean available){Map<String,Object> r=new HashMap<>();r.put("title",title);r.put("url",url);r.put("enabled",available&&v.menus.contains(url));Map<String,String> query=new HashMap<>();query.put(key,String.valueOf(value));r.put("query",query);return r;}
 @Transactional(readOnly=true)
 public Map<String,Object> detail(long id)throws Exception{
  Viewer v=viewer();long tenant=v.user.getTenantId();List<Object> args=new ArrayList<>(Arrays.asList(tenant,id));String from=" FROM jsh_factory_sales_order f JOIN jsh_depot_head h ON h.id=f.head_id AND h.tenant_id=f.tenant_id LEFT JOIN jsh_supplier c ON c.id=h.organ_id AND c.tenant_id=f.tenant_id WHERE f.tenant_id=? AND f.head_id=? AND IFNULL(h.delete_flag,'0')='0'"+scope(v,args);
  List<Map<String,Object>> orders=jdbc.queryForList("SELECT f.head_id,f.created_by,f.workflow_status,f.delivery_date,f.requirements,f.payment_terms,f.lines_json,h.number,h.total_price,c.supplier customer_name"+from,args.toArray());require(!orders.isEmpty(),"订单不存在或超出查看范围");Map<String,Object> o=orders.get(0);boolean full=v.all||num(o.get("created_by"))==v.user.getId();boolean money=v.money||num(o.get("created_by"))==v.user.getId();if(!money)o.remove("total_price");o.remove("created_by");JSONArray raw=JSON.parseArray(o.remove("lines_json").toString());
  List<Map<String,Object>> tasks=jdbc.queryForList("SELECT number,workflow_status,route_json FROM jsh_factory_production_task WHERE tenant_id=? AND head_id=?",tenant,id);JSONArray routes=tasks.isEmpty()?new JSONArray():JSON.parseArray(tasks.get(0).remove("route_json").toString());o.put("production",tasks.isEmpty()?null:tasks.get(0));o.put("scope",full?"本订单全部环节":"仅本车间任务数量，未汇总其他车间产量");
  Set<Integer> visible=new HashSet<>();Map<Integer,Integer> finalStages=new HashMap<>();Map<String,Map<String,Object>> stages=new LinkedHashMap<>();
  for(Object value:routes){JSONObject route=(JSONObject)value;int line=route.getIntValue("lineNo"),stage=route.getIntValue("stageNo"),workshop=route.getIntValue("workshopNo");finalStages.put(line,Math.max(finalStages.getOrDefault(line,0),stage));if(!full&&!v.workshops.contains(workshop))continue;visible.add(line);String k=routeKey(line,stage,workshop);Map<String,Object> row=stages.computeIfAbsent(k,key->{Map<String,Object> r=new HashMap<>();r.put("lineNo",line);r.put("stageNo",stage);r.put("workshopNo",workshop);r.put("input",BigDecimal.ZERO);r.put("output",BigDecimal.ZERO);r.put("loss",BigDecimal.ZERO);return r;});add(row,"planned",route.get("quantity"));}
  List<Map<String,Object>> reports=jdbc.queryForList("SELECT line_no,stage_no,workshop_no,input_quantity,output_quantity,loss_quantity FROM jsh_factory_production_report WHERE tenant_id=? AND head_id=?",tenant,id);
  for(Map<String,Object> r:reports){Map<String,Object> row=stages.get(routeKey((int)num(r.get("line_no")),(int)num(r.get("stage_no")),(int)num(r.get("workshop_no"))));if(row!=null){add(row,"input",r.get("input_quantity"));add(row,"output",r.get("output_quantity"));add(row,"loss",r.get("loss_quantity"));}}
  for(Map<String,Object> start:jdbc.queryForList("SELECT line_no,stage_no,workshop_no,actual_start FROM jsh_factory_production_start WHERE tenant_id=? AND head_id=?",tenant,id)){Map<String,Object> row=stages.get(routeKey((int)num(start.get("line_no")),(int)num(start.get("stage_no")),(int)num(start.get("workshop_no"))));if(row!=null)row.put("actualStart",start.get("actual_start"));}
  List<Map<String,Object>> reserved=jdbc.queryForList("SELECT line_no,quantity FROM jsh_factory_stock_reservation WHERE tenant_id=? AND head_id=?",tenant,id);JSONArray lines=new JSONArray();Set<Long> materials=new HashSet<>();
  for(int i=0;i<raw.size();i++){if(!full&&!visible.contains(i))continue;JSONObject p=raw.getJSONObject(i),line=new JSONObject();line.put("lineNo",i);for(String k:Arrays.asList("id","barCode","name","brand","standard","model","quantity"))line.put(k,p.get(k));if(money)line.put("price",p.get("price"));BigDecimal allocation=BigDecimal.ZERO,finalOutput=BigDecimal.ZERO;for(Map<String,Object> a:reserved)if(num(a.get("line_no"))==i)allocation=allocation.add(dec(a.get("quantity")));int last=finalStages.getOrDefault(i,0);for(Map<String,Object> r:stages.values())if(num(r.get("lineNo"))==i&&num(r.get("stageNo"))==last)finalOutput=finalOutput.add(dec(r.get("output")));line.put("reserved",allocation);line.put("finalStage",last);line.put("finalOutput",finalOutput);lines.add(line);materials.add(p.getLong("id"));}o.put("lines",lines);o.put("stages",stages.values());
  List<Map<String,Object>> inspections=jdbc.queryForList("SELECT id,line_no,stage_no,workshop_no,batch_number,quantity,parent_id,inspection_kind,workflow_status,qualified_quantity FROM jsh_factory_inspection WHERE tenant_id=? AND head_id=? ORDER BY id DESC",tenant,id);if(!full)inspections.removeIf(r->!v.workshops.contains((int)num(r.get("workshop_no"))));o.put("inspections",inspections);
  List<Map<String,Object>> materialsDocs=jdbc.queryForList("SELECT id,number,kind,line_no,stage_no,workshop_no,workflow_status FROM jsh_factory_material_request WHERE tenant_id=? AND task_head_id=? ORDER BY id DESC",tenant,id);if(!full)materialsDocs.removeIf(r->!v.workshops.contains((int)num(r.get("workshop_no"))));o.put("materials",materialsDocs);
  List<Map<String,Object>> transfers=jdbc.queryForList("SELECT tr.id,tr.inspection_id,tr.line_no,tr.stage_no,tr.workshop_no,i.workshop_no source_workshop,tr.batch_number,tr.quantity,tr.workflow_status FROM jsh_factory_quality_transfer tr JOIN jsh_factory_inspection i ON i.id=tr.inspection_id AND i.tenant_id=tr.tenant_id WHERE tr.tenant_id=? AND tr.head_id=? ORDER BY tr.id DESC",tenant,id);if(!full)transfers.removeIf(r->!v.workshops.contains((int)num(r.get("workshop_no")))&&!v.workshops.contains((int)num(r.get("source_workshop"))));o.put("transfers",transfers);
  List<Map<String,Object>> batches=jdbc.queryForList("SELECT f.id,f.line_no,i.workshop_no,f.batch_number,f.quantity,i.workflow_status qc_state,i.qualified_quantity,f.ledger_head_id,f.release_state,d.name depot_name FROM jsh_factory_finished_batch f JOIN jsh_factory_inspection i ON i.id=f.inspection_id AND i.tenant_id=f.tenant_id LEFT JOIN jsh_depot d ON d.id=f.depot_id AND d.tenant_id=f.tenant_id WHERE f.tenant_id=? AND f.head_id=? ORDER BY f.id DESC",tenant,id);if(!full)batches.removeIf(r->!v.workshops.contains((int)num(r.get("workshop_no"))));for(Map<String,Object> r:batches){String state=!"approved".equals(r.get("qc_state"))?("pending".equals(r.get("qc_state"))?"待质检主任确认":"待检测填报"):dec(r.get("qualified_quantity")).compareTo(dec(r.get("quantity")))<0?"不合格待处理":r.get("ledger_head_id")==null?"待整批入库":"released".equals(r.get("release_state"))?"已整批放行":"held".equals(r.get("release_state"))?"不予放行，待处理":"待领导放行";r.put("progress",state);}o.put("batches",batches);
  List<Map<String,Object>> shipments=jdbc.queryForList("SELECT workflow_status,requested_at,paid_by,paid_date,shipped_at,trucks_json FROM jsh_factory_shipment WHERE tenant_id=? AND head_id=?",tenant,id);for(Map<String,Object> sh:shipments){sh.put("truckCount",JSON.parseArray(sh.remove("trucks_json").toString()).size());sh.put("paid",sh.remove("paid_by")!=null);}o.put("shipment",shipments.isEmpty()?null:shipments.get(0));
  List<Map<String,Object>> changes=jdbc.queryForList("SELECT id,kind,workflow_status,created_at,applied_at FROM jsh_factory_order_change WHERE tenant_id=? AND head_id=? ORDER BY id DESC",tenant,id);o.put("changes",changes);
  List<Map<String,Object>> returns=jdbc.queryForList("SELECT r.id,r.workflow_status,r.created_at,r.received_at,di.material_id,l.quantity FROM jsh_factory_customer_return r JOIN jsh_factory_customer_return_line l ON l.return_id=r.id AND l.tenant_id=r.tenant_id JOIN jsh_depot_item di ON di.id=l.source_item_id AND di.tenant_id=l.tenant_id WHERE r.tenant_id=? AND r.source_head_id=? ORDER BY r.id DESC",tenant,id);if(!full)returns.removeIf(r->!materials.contains(num(r.get("material_id"))));o.put("returns",returns);
  List<Map<String,Object>> links=new ArrayList<>();links.add(jump(v,"销售订单","/bill/sale_order","orderId",id,true));links.add(jump(v,"库存核查与预留","/factory/stock_check","orderId",id,"approved".equals(o.get("workflow_status"))));links.add(jump(v,"生产任务与排班","/factory/production_task","viewId",id,!tasks.isEmpty()));links.add(jump(v,"领补退料","/factory/material_request","taskId",id,!tasks.isEmpty()));links.add(jump(v,"开工与生产日报","/factory/production_execution","taskId",id,!tasks.isEmpty()));links.add(jump(v,"半成品质检与流转","/factory/quality_transfer","taskId",id,!tasks.isEmpty()));links.add(jump(v,"成品质检、入库与放行","/factory/finished_product","taskId",id,!tasks.isEmpty()));links.add(jump(v,"收款确认、装车发货","/factory/shipping","orderId",id,"approved".equals(o.get("workflow_status"))));links.add(jump(v,"客户退货","/factory/returns",returns.isEmpty()?"orderNumber":"returnId",returns.isEmpty()?o.get("number"):returns.get(0).get("id"),true));links.add(jump(v,"订单变更与取消","/factory/order_change",changes.isEmpty()?"orderNumber":"changeId",changes.isEmpty()?o.get("number"):changes.get(0).get("id"),true));o.put("links",links);
  List<String> pending=new ArrayList<>();if("pending".equals(o.get("workflow_status")))pending.add("销售订单待审核");if("cancelled".equals(o.get("workflow_status")))pending.add("订单已取消，停止新增生产和发货，历史实物继续处理");for(Map<String,Object> ch:changes)if("pending".equals(ch.get("workflow_status")))pending.add("订单变更待领导审批，原计划继续");else if("approved".equals(ch.get("workflow_status")))pending.add("订单变更待统筹落实");for(Map<String,Object> r:batches)if(!"已整批放行".equals(r.get("progress")))pending.add(r.get("batch_number")+"："+r.get("progress"));if(shipments.isEmpty()&&"approved".equals(o.get("workflow_status")))pending.add("订单尚未申请发货，需核查整单预留和批次放行");if(!shipments.isEmpty()&&"requested".equals(shipments.get(0).get("workflow_status")))pending.add("prepay".equals(o.get("payment_terms"))&&!Boolean.TRUE.equals(shipments.get(0).get("paid"))?"款到发货：待财务确认到账":"待仓库装车及统一确认出库");for(Map<String,Object> r:returns)if(Arrays.asList("pending","approved").contains(r.get("workflow_status")))pending.add("退货TH"+r.get("id")+"："+("pending".equals(r.get("workflow_status"))?"待领导审批":"待仓库收货"));
  for(Map<String,Object> r:inspections)if(!"finished".equals(r.get("inspection_kind"))&&!"approved".equals(r.get("workflow_status")))pending.add("送检#"+r.get("id")+"："+("pending".equals(r.get("workflow_status"))?"待质检主任确认":"待检测填报"));
  for(Map<String,Object> r:transfers)if("pending".equals(r.get("workflow_status")))pending.add("交接#"+r.get("id")+"：待接收车间确认");
  for(Map<String,Object> r:materialsDocs)if("pending".equals(r.get("workflow_status")))pending.add(r.get("number")+"：待仓库确认");
  o.put("pending",new LinkedHashSet<>(pending));return o;
 }
}
